import * as React from "react"
import { ArrowDownIcon, ArrowUpIcon, CheckIcon, MinusIcon } from "lucide-react"
import { cn } from "@/lib/utils"

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"

/** Inclusive bounds of the normal range. */
export type VitalRange = { low: number; high: number }
export type VitalRanges = {
  /** Beats per minute. */
  heartRate: VitalRange
  /** mmHg. */
  systolic: VitalRange
  /** mmHg. */
  diastolic: VitalRange
  /** Percent. */
  spo2: VitalRange
  /** In the panel's temperature unit. */
  temperature: VitalRange
  /** Breaths per minute. */
  respiratoryRate: VitalRange
}
export type VitalReadings = {
  heartRate?: number | null
  systolic?: number | null
  diastolic?: number | null
  spo2?: number | null
  temperature?: number | null
  respiratoryRate?: number | null
}
export type VitalSign =
  "heartRate" | "bloodPressure" | "spo2" | "temperature" | "respiratoryRate"
export type VitalStatus = "low" | "normal" | "high" | "missing"
export type TemperatureUnit = "celsius" | "fahrenheit"
export type VitalSignsProps = {
  readings: VitalReadings
  /** Merged over `adultVitalRanges`, one vital at a time. */
  ranges?: Partial<VitalRanges>
  /** Which vitals to show, in order. */
  vitals?: readonly VitalSign[]
  /** The unit of `readings.temperature` and `ranges.temperature`. */
  temperatureUnit?: TemperatureUnit
  /** Used to format numbers. */
  locale?: string
  title?: string
  /** Shown under the title, such as when the readings were taken. */
  description?: React.ReactNode
  className?: string
}

/**
 * Common resting adult ranges, as a starting point rather than clinical
 * guidance. Temperature is in degrees Celsius.
 */
export const adultVitalRanges: VitalRanges = {
  heartRate: { low: 60, high: 100 },
  systolic: { low: 90, high: 120 },
  diastolic: { low: 60, high: 80 },
  spo2: { low: 95, high: 100 },
  temperature: { low: 36.1, high: 37.2 },
  respiratoryRate: { low: 12, high: 20 },
}
export const defaultVitals: readonly VitalSign[] = [
  "heartRate",
  "bloodPressure",
  "spo2",
  "temperature",
]

export function vitalStatus(
  value: number | null | undefined,
  range: VitalRange
): VitalStatus {
  if (value == null || !Number.isFinite(value)) return "missing"
  if (value < range.low) return "low"
  if (value > range.high) return "high"
  return "normal"
}

/** High wins over low, so a reading that is both reads as high. */
export function bloodPressureStatus(
  systolic: VitalStatus,
  diastolic: VitalStatus
): VitalStatus {
  if (systolic === "missing" || diastolic === "missing") return "missing"
  if (systolic === "high" || diastolic === "high") return "high"
  if (systolic === "low" || diastolic === "low") return "low"
  return "normal"
}

function celsiusToFahrenheit({ low, high }: VitalRange): VitalRange {
  const convert = (value: number) =>
    Math.round(((value * 9) / 5 + 32) * 10) / 10
  return { low: convert(low), high: convert(high) }
}

/**
 * Resolves the ranges a panel uses: defaults converted to the temperature
 * unit, then any overrides as given.
 */
export function resolveVitalRanges(
  ranges: Partial<VitalRanges> = {},
  temperatureUnit: TemperatureUnit = "celsius"
): VitalRanges {
  const defaults =
    temperatureUnit === "fahrenheit"
      ? {
          ...adultVitalRanges,
          temperature: celsiusToFahrenheit(adultVitalRanges.temperature),
        }
      : adultVitalRanges
  return { ...defaults, ...ranges }
}

export type VitalAssessment = {
  vital: VitalSign
  label: string
  unit: string
  /** Formatted value, or null without a reading. */
  value: string | null
  /** Formatted normal range. */
  range: string
  status: VitalStatus
  /** Status as text, which never relies on colour. */
  statusLabel: string
}

const statusLabels: Record<VitalStatus, string> = {
  low: "Low",
  normal: "Normal",
  high: "High",
  missing: "No reading",
}

export function assessVital(
  vital: VitalSign,
  readings: VitalReadings,
  ranges: VitalRanges,
  temperatureUnit: TemperatureUnit = "celsius",
  locale = "en-US"
): VitalAssessment {
  const format = (value: number, digits = 0) =>
    value.toLocaleString(locale, {
      minimumFractionDigits: digits,
      maximumFractionDigits: digits,
    })
  const span = ({ low, high }: VitalRange, digits = 0) =>
    `${format(low, digits)}–${format(high, digits)}`
  if (vital === "bloodPressure") {
    const systolic = vitalStatus(readings.systolic, ranges.systolic)
    const diastolic = vitalStatus(readings.diastolic, ranges.diastolic)
    const status = bloodPressureStatus(systolic, diastolic)
    // Name the out-of-range part when only one is, or when they disagree.
    const parts = [
      systolic !== "normal" ? `${systolic} systolic` : null,
      diastolic !== "normal" ? `${diastolic} diastolic` : null,
    ].filter((part) => part !== null)
    const detail =
      status === "missing" || status === "normal" || systolic === diastolic
        ? statusLabels[status]
        : parts.join(", ").replace(/^./, (letter) => letter.toUpperCase())
    return {
      vital,
      label: "Blood pressure",
      unit: "mmHg",
      value:
        status === "missing"
          ? null
          : `${format(readings.systolic!)}/${format(readings.diastolic!)}`,
      range: `${span(ranges.systolic)} / ${span(ranges.diastolic)}`,
      status,
      statusLabel: detail,
    }
  }
  const meta = {
    heartRate: { label: "Heart rate", unit: "bpm", digits: 0 },
    spo2: { label: "SpO₂", unit: "%", digits: 0 },
    temperature: {
      label: "Temperature",
      unit: temperatureUnit === "fahrenheit" ? "°F" : "°C",
      digits: 1,
    },
    respiratoryRate: { label: "Respiratory rate", unit: "/min", digits: 0 },
  }[vital]
  const value = readings[vital]
  const status = vitalStatus(value, ranges[vital])
  return {
    vital,
    label: meta.label,
    unit: meta.unit,
    value: status === "missing" ? null : format(value!, meta.digits),
    range: span(ranges[vital], meta.digits),
    status,
    statusLabel: statusLabels[status],
  }
}

// Each status has its own shape, so it reads without colour as well as with
// the text beside it.
function StatusIcon({
  status,
  className,
}: {
  status: VitalStatus
  className?: string
}) {
  switch (status) {
    case "normal":
      return (
        <CheckIcon
          aria-hidden="true"
          className={cn("size-3.5 shrink-0", className)}
        />
      )
    case "high":
      return (
        <ArrowUpIcon
          aria-hidden="true"
          className={cn("size-3.5 shrink-0", className)}
        />
      )
    case "low":
      return (
        <ArrowDownIcon
          aria-hidden="true"
          className={cn("size-3.5 shrink-0", className)}
        />
      )
    case "missing":
      return (
        <MinusIcon
          aria-hidden="true"
          className={cn("size-3.5 shrink-0", className)}
        />
      )
  }
}

export function VitalSigns({
  readings,
  ranges,
  vitals = defaultVitals,
  temperatureUnit = "celsius",
  locale = "en-US",
  title = "Vital signs",
  description,
  className,
}: VitalSignsProps) {
  const resolved = resolveVitalRanges(ranges, temperatureUnit)
  return (
    <Card role="region" aria-label={title} className={cn("w-full", className)}>
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        {description != null && (
          <CardDescription>{description}</CardDescription>
        )}
      </CardHeader>
      <CardContent>
        <dl className="grid grid-cols-[repeat(auto-fit,minmax(9.5rem,1fr))] gap-3">
          {vitals.map((vital) => {
            const item = assessVital(
              vital,
              readings,
              resolved,
              temperatureUnit,
              locale
            )
            const abnormal = item.status === "low" || item.status === "high"
            return (
              <div
                key={vital}
                data-vital={vital}
                data-status={item.status}
                className={cn(
                  "flex min-w-0 flex-col gap-1.5 rounded-lg border p-3",
                  abnormal && "border-destructive"
                )}
              >
                <dt className="text-xs font-medium text-muted-foreground">
                  {item.label}
                </dt>
                <dd className="flex items-baseline gap-1">
                  {item.value === null ? (
                    <span
                      aria-hidden="true"
                      className="text-2xl font-semibold text-muted-foreground"
                    >
                      —
                    </span>
                  ) : (
                    <>
                      <span className="text-2xl font-semibold tabular-nums">
                        {item.value}
                      </span>
                      <span className="text-xs text-muted-foreground">
                        {item.unit}
                      </span>
                    </>
                  )}
                </dd>
                <dd
                  className={cn(
                    "flex items-center gap-1 text-xs",
                    abnormal
                      ? "font-semibold text-foreground"
                      : "font-medium text-muted-foreground"
                  )}
                >
                  <StatusIcon
                    status={item.status}
                    className={abnormal ? "text-destructive" : undefined}
                  />
                  {item.statusLabel}
                </dd>
                <dd className="text-xs text-muted-foreground tabular-nums">
                  Normal {item.range} {item.unit}
                </dd>
              </div>
            )
          })}
        </dl>
      </CardContent>
    </Card>
  )
}

/**
 * Theme tokens for clinical and anatomy pieces.
 *
 * OrganUI ships fixed anatomical colours. Retana UI items inherit the host
 * theme instead, so every structure, trace and fill names a token and an
 * optional lightness shade. SVG and CSS use the token directly; WebGL reads
 * the resolved token once per theme change.
 */
export type ClinicalTone =
  | "chart-1"
  | "chart-2"
  | "chart-3"
  | "chart-4"
  | "chart-5"
  | "primary"
  | "destructive"
  | "muted-foreground"
  | "foreground"

export const CLINICAL_TONES: readonly ClinicalTone[] = [
  "chart-1",
  "chart-2",
  "chart-3",
  "chart-4",
  "chart-5",
]

/** CSS value for a tone. shade -1..1 mixes toward background (+) or foreground (-). */
export function toneVar(tone: ClinicalTone, shade = 0) {
  if (!shade) return `var(--${tone})`
  const pct = Math.round(Math.min(Math.abs(shade), 1) * 100)
  return shade > 0
    ? `color-mix(in oklch, var(--${tone}), var(--background) ${pct}%)`
    : `color-mix(in oklch, var(--${tone}), var(--foreground) ${pct}%)`
}

/** A tone picked by position, for series without a fixed meaning. */
export function toneAt(index: number): ClinicalTone {
  return CLINICAL_TONES[((index % CLINICAL_TONES.length) + CLINICAL_TONES.length) % CLINICAL_TONES.length]!
}

export type Rgb = readonly [number, number, number]

const cache = new Map<string, Rgb>()
let probe: CanvasRenderingContext2D | null | undefined

/**
 * Resolve any CSS colour expression (tokens, color-mix) to sRGB 0..1 by
 * painting one pixel. Returns null outside the browser.
 */
export function resolveCssColor(value: string, scope?: Element | null): Rgb | null {
  if (typeof document === "undefined") return null
  const key = value
  const hit = cache.get(key)
  if (hit) return hit
  const host = document.createElement("span")
  host.style.color = value
  host.style.display = "none"
  ;(scope ?? document.body).appendChild(host)
  const computed = getComputedStyle(host).color
  host.remove()
  if (probe === undefined) {
    const canvas = document.createElement("canvas")
    canvas.width = canvas.height = 1
    probe = canvas.getContext("2d", { willReadFrequently: true })
  }
  if (!probe || !computed) return null
  probe.clearRect(0, 0, 1, 1)
  probe.fillStyle = computed
  probe.fillRect(0, 0, 1, 1)
  const [r, g, b] = probe.getImageData(0, 0, 1, 1).data
  const rgb: Rgb = [r! / 255, g! / 255, b! / 255]
  cache.set(key, rgb)
  return rgb
}

/** Drop resolved colours, for example after the host switches theme. */
export function clearToneCache() {
  cache.clear()
}

/** Call back when the document theme class or style changes. */
export function onThemeChange(callback: () => void) {
  if (typeof MutationObserver === "undefined" || typeof document === "undefined") return () => {}
  const observer = new MutationObserver(() => {
    clearToneCache()
    callback()
  })
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style", "data-theme"] })
  return () => observer.disconnect()
}
